 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # A straight 5-bar acts as a copier: its adjacent colored motif is
    # extended along the bar, repeating the motif if it is multiple cells long.
    # Horizontal bars copy the vertical motif below their left endpoint.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (c > 0 and grid[r][c - 1] == 5):
                continue
            end = c
            while end + 1 < w and grid[r][end + 1] == 5:
                end += 1
            motif = []
            rr = r + 1
            while rr < h and grid[rr][c] not in (0, 5):
                motif.append(grid[rr][c])
                rr += 1
            if motif:
                for cc in range(c, end + 1):
                    for k, value in enumerate(motif):
                        if r + 1 + k < h:
                            out[r + 1 + k][cc] = value

    # Vertical bars copy the horizontal pattern at the bottom endpoint,
    # repeating a multi-row motif upwards along the bar.
    for c in range(w):
        for r in range(h):
            if grid[r][c] != 5 or (r > 0 and grid[r - 1][c] == 5):
                continue
            end = r
            while end + 1 < h and grid[end + 1][c] == 5:
                end += 1
            # Identify the attached block immediately to the right of the
            # bottom of the bar, retaining each row of its motif.
            motif = []
            rr = end
            while rr >= r:
                row = []
                cc = c + 1
                while cc < w and grid[rr][cc] not in (0, 5):
                    row.append(grid[rr][cc])
                    cc += 1
                if not row:
                    break
                motif.append(row)
                rr -= 1
            if motif:
                motif.reverse()
                for offset in range(end - r + 1):
                    source = motif[len(motif) - 1 - (offset % len(motif))]
                    target_r = end - offset
                    for k, value in enumerate(source, 1):
                        if c + k < w:
                            out[target_r][c + k] = value
    return out

